  const off = t; // cell x maps to index x + t + off
  for (let j = 0; j < 2 * t + 1; j++) cur[j + off] = (bits >>> j) & 1;
  for (let s = 0; s < t; s++) {
    for (let i = 1; i < W - 1; i++) {
      nxt[i] = tab[4 * cur[i - 1] + 2 * cur[i] + cur[i + 1]];
    }
    nxt[0] = 0; nxt[W - 1] = 0;
    const tmp = cur; cur = nxt; nxt = tmp;
  }
  return cur[t + off];
}

