  for (let m = 0; m < N; m++) f[m] = centreCell(tab, t, m);
  // count of black outputs, as a sanity figure (window_count_half says exactly half for rule 30)
  let ones = 0;
  for (let m = 0; m < N; m++) ones += f[m];
