  const t = table(r);
  const c0 = t[0];
  const cl = t[4] ^ c0, cc = t[2] ^ c0, cr = t[1] ^ c0;
  for (let l = 0; l < 2; l++) for (let c = 0; c < 2; c++) for (let rr = 0; rr < 2; rr++) {
